function speak(text: string, accent: Accent, rate = 0.88) {
  if (!("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = accent === "british" ? "en-GB" : "en-US";
  utterance.rate = rate;
  const matchingVoice = window.speechSynthesis.getVoices().find((voice) => accent === "british" ? /en[-_]GB|United Kingdom/i.test(`${voice.lang} ${voice.name}`) : /en[-_]US|United States/i.test(`${voice.lang} ${voice.name}`));
  if (matchingVoice) utterance.voice = matchingVoice;
  window.speechSynthesis.speak(utterance);
}

function ProgressRing({ value }: { value: number }) {
  return (
    <div className="relative grid h-14 w-14 place-items-center rounded-full" style={{ background: `conic-gradient(#e7b84a ${value * 3.6}deg, rgba(255,255,255,.16) 0deg)` }}>
      <div className="grid h-10 w-10 place-items-center rounded-full bg-[#253453] text-xs font-bold text-white">{value}%</div>
    </div>
  );
}

